-- Importation des réparations
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET AUTOCOMMIT = 0;
START TRANSACTION;


COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
SET UNIQUE_CHECKS = 1;
SET AUTOCOMMIT = 1;

-- Vérifications
SELECT COUNT(*) as total_reparations FROM reparations;
SELECT COUNT(*) as reparations_importees FROM reparations WHERE id >= 2000;
SELECT COUNT(*) as orphaned_reparations FROM reparations r LEFT JOIN clients c ON r.client_id = c.id WHERE c.id IS NULL;
